const ee = require('@google/earthengine');
const privateKey = require('./test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const region = ee.FeatureCollection('FAO/GAUL/2015/level1')
    .filter(ee.Filter.inList('ADM1_NAME', ['Punjab', 'Haryana']))
    .geometry();

  const startYear = 2012;
  const endYear = 2024;
  const targetYear = 2016;

  // 2. Data Acquisition & Check
  // MODIS MCD14ML Thermal Anomalies / Fire Daily Global
  const fireCollection = ee.ImageCollection('MODIS/051/MCD14ML');

  const annualFireCounts = ee.List.sequence(startYear, endYear).map(function(year) {
    year = ee.Number(year);
    const startDate = ee.Date.fromYMD(year, 1, 1);
    const endDate = ee.Date.fromYMD(year, 12, 31);

    const yearCollection = fireCollection
      .filterDate(startDate, endDate)
      .filterBounds(region);

    // Check if the collection for the year is empty
    return ee.Algorithms.If(
      yearCollection.size().eq(0),
      ee.Dictionary({ 'year': year, 'count': -1, 'hasData': false }), // Indicate no data
      ee.Dictionary({ 'year': year, 'count': yearCollection.size(), 'hasData': true })
    );
  }).getInfo();

  let hasDataIssue = false;
  let allAnnualCounts = [];
  let printOutput = [];

  // Check for empty collections
  for (const entry of annualFireCounts) {
    if (!entry.hasData) {
      printOutput.push(`Images for year ${entry.year}: 0`);
      hasDataIssue = true;
    } else {
      printOutput.push(`Images for year ${entry.year}: ${entry.count}`);
    }
  }

  if (hasDataIssue) {
    console.log(printOutput.join('\n'));
    console.log("C1: Empty Collection (No images found for one or more years in the specified region/date).");
    return;
  }

  // 3. Processing & Calculation
  // Filter for high confidence fires and count pixels
  const annualPixelCounts = ee.List.sequence(startYear, endYear).map(function(year) {
    year = ee.Number(year);
    const startDate = ee.Date.fromYMD(year, 1, 1);
    const endDate = ee.Date.fromYMD(year, 12, 31);

    const yearCollection = fireCollection
      .filterDate(startDate, endDate)
      .filterBounds(region);

    // Filter for confidence >= 70 (nominal and high confidence)
    // The 'confidence' band is in percent.
    const fires = yearCollection.filter(ee.Filter.gte('confidence', 70));

    // Create a binary image where fire pixels are 1 and non-fire are 0
    const firePixels = fires.map(function(image) {
      return image.select('confidence').unitScale(70, 100).multiply(1).rename('fire_detection');
    });

    // Sum the fire detections for the year
    const totalFireForYear = firePixels.sum();

    // Calculate total fire pixels in the region for the year
    // Use a relatively coarse scale to avoid memory issues and speed up
    // scale for MODIS is 1km. So using 1000m scale.
    const fireCountReducer = totalFireForYear.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: region,
      scale: 1000, // MODIS resolution is ~1km
      maxPixels: 1e9,
      crs: 'EPSG:4326', // Explicitly setting CRS to avoid projection issues
    });

    const count = ee.Number(fireCountReducer.get('fire_detection'));

    return ee.Algorithms.If(
      count.eq(0),
      ee.Dictionary({ 'year': year, 'pixel_count': 0, 'isValid': false }), // Indicate 0 valid pixels
      ee.Dictionary({ 'year': year, 'pixel_count': count, 'isValid': true })
    );
  }).getInfo();

  // Store counts and check for C2 (No Valid Pixels)
  let pixelCountsByYear = {};
  let noValidPixelsIssue = false;

  for (const entry of annualPixelCounts) {
    pixelCountsByYear[entry.year] = entry.pixel_count;
    if (entry.pixel_count === 0 && entry.isValid === false) { // 0 count after processing.
      noValidPixelsIssue = true;
    }
    printOutput.push(`Year ${entry.year} Total Fire Detections: ${entry.pixel_count}`);
  }

  if (noValidPixelsIssue) {
    console.log(printOutput.join('\n'));
    console.log("C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain for one or more years).");
    return;
  }

  // 4. Comparison and Final Answer
  const targetYearCount = pixelCountsByYear[targetYear];
  if (targetYearCount === undefined || targetYearCount === null) {
      console.log(printOutput.join('\n'));
      console.log("C3: Calculation Failure (Result for target year is None, NaN, or invalid).");
      return;
  }

  let maxCount = 0;
  let maxYear = null;

  for (let year = startYear; year <= endYear; year++) {
    const currentCount = pixelCountsByYear[year];
    if (currentCount > maxCount) {
      maxCount = currentCount;
      maxYear = year;
    }
  }

  printOutput.push(`\nTarget Year (${targetYear}) Fire Detections: ${targetYearCount}`);
  printOutput.push(`Year with Most Fire Detections: ${maxYear} (${maxCount})`);

  console.log(printOutput.join('\n'));

  if (targetYearCount === maxCount) {
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
